"INSERT INTO fields (parent_id, level, name_ar, def, sup_name, ord) SELECT (SELECT id FROM fields WHERE level = 2 AND name_ar = 'خدمات الفئات الاجتماعية' AND parent_id = (SELECT id FROM fields WHERE level = 1 AND name_ar = 'الخدمات الاجتماعية')), 3, 'خدمات المسنين', 'المنظمات التي تقدم رعاية للمسنين (غير طبية)، بما في ذلك الخدمات التي تقدم في المنزل، وخدمات الأعمال المنزلية والنقل والترفيه وبرامج الوجبات الغذائية والخدمات الأخرى الموجَّهة نحو كبار السن (لا تدخل فيها دور رعاية الصحية للمسنين)', 'وزارة الموارد البشرية والتنمية الاجتماعية', 40005 WHERE true ON CONFLICT(parent_id, name_ar) DO UPDATE SET def = excluded.def, sup_name = excluded.sup_name, ord = excluded.ord;",
"INSERT INTO fields (parent_id, level, name_ar, def, sup_name, ord) SELECT (SELECT id FROM fields WHERE level = 2 AND name_ar = 'خدمات الفئات الاجتماعية' AND parent_id = (SELECT id FROM fields WHERE level = 1 AND name_ar = 'الخدمات الاجتماعية')), 3, 'خدمات تعزيز الاعتماد على الذات والخدمات الاجتماعية الأخرى للأفراد', 'برامج تعزيز القدرة على الاعتماد على الذات والتنمية الشخصية، بما في ذلك مجموعات الدعم وتقديم الاستشارات الشخصية وتقديم المشورة فيما يتصل بالادخار والإتمان وإدارة المال.', 'وزارة الموارد البشرية والتنمية الاجتماعية', 40006 WHERE true ON CONFLICT(parent_id, name_ar) DO UPDATE SET def = excluded.def, sup_name = excluded.sup_name, ord = excluded.ord;",
