"INSERT INTO fields (parent_id, level, name_ar, def, sup_name, ord) SELECT (SELECT id FROM fields WHERE level = 2 AND name_ar = 'خدمات الفئات الاجتماعية' AND parent_id = (SELECT id FROM fields WHERE level = 1 AND name_ar = 'الخدمات الاجتماعية')), 3, 'خدمات النقل للمسنين', 'المنظمات التي تقدم جميع خدمات النقل للمسنين فيما يخدم تنقلاتهم (النقل البري - النقل الجوي - النقل البحري - النقل السككي )', 'وزارة النقل والخدمات اللوجستية', 40009 WHERE true ON CONFLICT(parent_id, name_ar) DO UPDATE SET def = excluded.def, sup_name = excluded.sup_name, ord = excluded.ord;",
"INSERT INTO fields (parent_id, level, name_ar, ord) SELECT (SELECT id FROM fields WHERE level = 1 AND name_ar = 'الخدمات الاجتماعية'), 2, 'الطوارئ والإغاثة', 401 WHERE true ON CONFLICT(parent_id, name_ar) DO UPDATE SET ord = excluded.ord;",
