"INSERT INTO fields (parent_id, level, name_ar, official, def, ord) VALUES (NULL, 1, 'البيئة', 'البيئة', 'المنظمات التي تعزز وتوفر الخدمات التي تٌعنى بالمحافظة على البيئة ومكافحة التلوث والوقاية والتثقيف البيئي والصحي، وحماية الحيوان', 5) ON CONFLICT(name_ar) WHERE parent_id IS NULL DO UPDATE SET official = excluded.official, def = excluded.def, ord = excluded.ord;",
