"INSERT INTO fields (parent_id, level, name_ar, def, sup_name, ord) SELECT (SELECT id FROM fields WHERE level = 2 AND name_ar = 'البيئة' AND parent_id = (SELECT id FROM fields WHERE level = 1 AND name_ar = 'البيئة')), 3, 'خدمة الحفاظ على الموارد المائية', 'الحفاظ على الموارد المائية وحمايتها ، بما في ذلك السدود والابار وجميع مصادر المياه', 'وزارة البيئة والمياه والزراعة', 50000 WHERE true ON CONFLICT(parent_id, name_ar) DO UPDATE SET def = excluded.def, sup_name = excluded.sup_name, ord = excluded.ord;",
