"INSERT INTO fields (parent_id, level, name_ar, def, sup_name, ord) SELECT (SELECT id FROM fields WHERE level = 2 AND name_ar = 'البيئة' AND parent_id = (SELECT id FROM fields WHERE level = 1 AND name_ar = 'البيئة')), 3, 'خدمات الحفاظ على الموارد الطبيعية وحمايتها', 'الحفاظ على الموارد الطبيعية وحمايتها، بما في ذلك الأراضي والطاقة والموارد النباتية للاستعمال العام والتمتع بالحياة', 'وزارة البيئة والمياه والزراعة', 50002 WHERE true ON CONFLICT(parent_id, name_ar) DO UPDATE SET def = excluded.def, sup_name = excluded.sup_name, ord = excluded.ord;",
"INSERT INTO fields (parent_id, level, name_ar, def, sup_name, ord) SELECT (SELECT id FROM fields WHERE level = 2 AND name_ar = 'البيئة' AND parent_id = (SELECT id FROM fields WHERE level = 1 AND name_ar = 'البيئة')), 3, 'خدمات تجميل وتخطيط المناطق الحضرية', 'المنظمات التي تقدم برامج تخطيط وتجميل المدن ، ومن ذلك خدمات تجميل الأحياء والطرق ، وبرامج الحفاظ على الحدائق والمساحات الخضراء والمفتوحة في المناطق الحضرية والريفية ، وتنظيم حملات لمكافحة إلقاء المهملات ومعالجة التشوه البصري وتحسين مظهر المدينة ، وكذلك المنظمات التي تعنى بتقديم البرامج والخدمات في مجال السياسات البلدية والقروية ، وتخطيط المدن .', 'وزارة البلديات والإسكان', 50003 WHERE true ON CONFLICT(parent_id, name_ar) DO UPDATE SET def = excluded.def, sup_name = excluded.sup_name, ord = excluded.ord;",
