"INSERT INTO fields (parent_id, level, name_ar, official, def, ord) VALUES (NULL, 1, 'التنمية والإسكان', 'التنمية و الإسكان', 'المنظمات التي تعزز البرامج و الخدمات للمساعدة في تحسين المجتمعات وتحقيق الرفاه الاقتصادي والاجتماعي للمجتمع', 6) ON CONFLICT(name_ar) WHERE parent_id IS NULL DO UPDATE SET official = excluded.official, def = excluded.def, ord = excluded.ord;",
