"INSERT INTO fields (parent_id, level, name_ar, def, sup_name, ord) SELECT (SELECT id FROM fields WHERE level = 2 AND name_ar = 'التنمية الاجتماعية والاقتصادية والمجتمعية' AND parent_id = (SELECT id FROM fields WHERE level = 1 AND name_ar = 'التنمية والإسكان')), 3, 'الفندقة ودور الضيافة السياحية', 'المنظمات التي تعمل في إدارة وإنشاء وتشغيل الفنادق ودور الضيافة السياحية', 'وزارة السياحة', 60001 WHERE true ON CONFLICT(parent_id, name_ar) DO UPDATE SET def = excluded.def, sup_name = excluded.sup_name, ord = excluded.ord;",
"INSERT INTO fields (parent_id, level, name_ar, def, sup_name, ord) SELECT (SELECT id FROM fields WHERE level = 2 AND name_ar = 'التنمية الاجتماعية والاقتصادية والمجتمعية' AND parent_id = (SELECT id FROM fields WHERE level = 1 AND name_ar = 'التنمية والإسكان')), 3, 'منظمات دعم ريادة الاعمال', 'المنظمات التي تعنى بتمكين رواد الأعمال لبدء مشاريعهم وتنميتها، وتوفير وسائل لتحفيز رواد الأعمال ومعالجة التحديات التي تواجه مشاريعهم الناشئة وتسهم في تحقيق نجاحها واستدامتها. وإيجاد بيئة استثمار جاذبة ومستدامة من المبادرات مثل التدريب والإرشاد وحلول التمويل والاستثمار، وتقديم برامج الاحتضان ومسرعات الأعمال و تنفيذ ودعم البرامج والمشاريع و نشر ثقافة وفكر العمل الحر ريادة الأعمال ، توفير مساحة للعمل وخدمات لتطوير الأعمال وخدمات إستشارية وتوجيهية وتدريبية وتوفير مساحات عمل مشتركة لتسريع نمو الاعمال الريادية الناشئة.', 'وزارة التجارة', 60002 WHERE true ON CONFLICT(parent_id, name_ar) DO UPDATE SET def = excluded.def, sup_name = excluded.sup_name, ord = excluded.ord;",
